import json,copy,work
R={'claim':'c','conditions':{'a':1}}
P={'required_conditions':['a'],'require_verified':True}
E=[{'source':'old','claim':'c','value':1,'conditions':{'a':1},'verified':True},{'source':'new','claim':'c','value':2,'conditions':{'a':1},'verified':True,'supersedes':['old']}]
r0,e0,p0=copy.deepcopy(R),copy.deepcopy(E),copy.deepcopy(P)
assert work.evaluate(R,E,P)=={'status':'supported','value':2,'sources':['new'],'unknowns':[]}
assert work.evaluate({'claim':'c','conditions':{}},E,P)=={'status':'unknown','value':None,'sources':[],'unknowns':['a']}
assert work.evaluate({'claim':'z','conditions':{'a':1}},E,P)=={'status':'unknown','value':None,'sources':[],'unknowns':['no matching evidence']}
assert (R,E,P)==(r0,e0,p0)
print('checks passed')

